import React, { useState, useEffect } from "react";
import { fetchStructDataWithFilters } from "../api/fetch_records";
import { parseDMS } from "../utils/converters";

const EditableWaterReport = () => {
    // Храним счётные записи
  const [records, setRecords] = useState([]);
  // Поля, которые пользователь может сам дополнять (месяцы)
  // const [formData, setFormData] = useState({ month1: "", month2: "", month3: "" });
  // const [formData, setFormData] = useState({
  //   organisation: "",
  //   address: "",
  //   inn: "",
  //   opf: "",
  //   district: "",
  //   region: "",
  //   reopCode: "",
  //   reopName: "",
  //   areaCode: "",
  //   areaName: "",
  //   agreement: "",
  //   meterType: "",
  //   checkDate: "",
  //   objectName: "",
  //   objectType: "",
  //   category: "",
  //   latitude: "",
  //   longitude: "",
  //   permittedVolume: "",
  //   actualVolume: "",
  //   month1: "",
  //   month2: "",
  //   month3: ""
  // });

  useEffect(() => {
    const fetchData = async () => {
      const org = JSON.parse(localStorage.getItem("org"));
      if (!org || !org.id) {
        console.error("org.id не найден в localStorage");
        return;
      }

      const data = await fetchStructDataWithFilters("get_struct31", { org_id: org.id });

      if (!data || data.status !== "success") {
        console.error("Ошибка при получении данных:", data?.message);
        return;
      }

      const record = data.data?.[0]; // Пока берём первую точку (или делаем выбор позже)
      if (!record) return;

      setFormData(prev => ({
        ...prev,
        organisation: org.organisation_name || "",
        inn: org.inn || "",
        address: org.address || "",
        meterType: record?.meter?.brand || "",
        checkDate: record?.meter?.check_date || "",
        objectName: record?.water_object?.name || "",
        objectCode: record?.water_object?.code_obj?.code || "",
        objectType: record?.water_object?.code_type?.code || "",
        category: record?.water_object?.category || "ПО",
        pointNumber: record?.point_id || "1",
        allowedVolume: record?.permission?.allowed_volume?.toString() || "",
        latitude: record?.latitude_longitude?.split("_")[0] || "",
        longitude: record?.latitude_longitude?.split("_")[1] || "",
        // остальные — подставим при наличии
      }));
    };

    fetchData();
  }, []);


  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  return (
    <div className="water-report">
      <h2>Сведения, полученные в результате учета объема забора (изъятия) водных ресурсов из водных объектов</h2>
      <div className="subtitle">за <select> <option value="">Выбрать</option>
                <option value="1">1 </option>
                <option value="2">2</option>
                <option value="3">3 </option>
                <option value="4">4</option>  
                </select> квартал <select> <option value="">Выбрать</option>
                <option value="2025">2025 </option>
                <option value="2024">2024</option>
                <option value="2023">2023 </option>
                <option value="2022">2022</option> </select>  г. | Форма 3.1</div>

      <table className="info-table">
        <tbody>
          <tr>
            <td>Наименование организации</td>
            <td colSpan="3">
              <input name="organisation" value={formData.organisation} onChange={handleChange} />
            </td>
          </tr>
          <tr>
