            <td>Регион</td>
            <td><input name="region" value={formData.region} onChange={handleChange} /></td>
          </tr>
          <tr>
            <td>Наименование и код гидрографической единицы</td>
            <td >
              <select name="reopCode" value={formData.reopCode} onChange={handleChange}>
                <option value="">Выбрать</option>
                <option value="13.01.03.002">13.01.02</option>
                <option value="13.01.03.003">13.01.03</option>
              </select>
              </td>
              <td colSpan="2">
              <input name="reopName" value={formData.reopName} onChange={handleChange} />
            </td>
          </tr>
          <tr>
            <td>Водохозяйственный участок</td>
            <td >
              <select name="areaCode" value={formData.areaCode} onChange={handleChange}>
                <option value="">Выбрать</option>
                <option value="13.01.02.002">13.01.02.002</option>
                <option value="13.01.03.003">13.01.03.003</option>
              </select>
              </td>
              <td colSpan="2">
              <input name="areaName" value={formData.areaName} onChange={handleChange} />
            </td>
          </tr>
          <tr>
            <td>Реквизиты договора</td>
            <td colSpan="2">
            Регистрационный № Договора водопользования
              <input name="agreement" value={formData.agreement} onChange={handleChange} />
            </td>
            <tr>
            <td>
            Дата начало
            <input  type="date" name="agreement" value={formData.agreement} onChange={handleChange} />  
            </td>
            <td colSpan="1">Дата окончания
            <input  type="date" name="agreement" value={formData.agreement} onChange={handleChange} />  
